/* 0b3e: pick a listed weapon type and show its panel; end is the list's
 * end pointer. */
void opeu_view_weapon_list(uint8_t ds[65536], HostEvent event, uint16_t sp,
                           LIST_P end) {
  uint8_t a, b;
  VW_USE();
  a = WEAPON_COUNT(end);
  SET_COUNT(a + 1);
  SET_CHECK();
  for (b = 7; MESSAGE(PROMPT, RECORD3), DIALOG(b); b = 6) {
    TYPE_PANEL(WEAPON(ROW));
    MESSAGE(HERE, RECORD3);
  }
}

